input.script:
listing = boundary retry 3 {
    first = list_orders({ month: "2026-03", page: 1 })
    rest = for page in list.range(2, first.total_pages + 1) {
        r = boundary retry 3 { return list_orders({ month: "2026-03", page: page }) } catch err {
            return fail("LIST", err.code + ": " + err.message)
        }
        return r.items
    }
    items = fold acc = first.items for page_items in rest { return acc + page_items }
    return items
} catch err {
    return fail("LIST_ALL", err.code + ": " + err.message)
}

enriched = for order in listing {
    detail = boundary retry 3 { return get_order({ id: order.id }) } catch err {
        return fail("ORDER", err.code + ": " + err.message)
    }
    skip if detail.status != "completed"
    customer = boundary retry 3 { return get_customer({ id: order.customer_id }) } catch err {
        return fail("CUST", err.code + ": " + err.message)
    }
    return { region: customer.region, amount: detail.amount_cents }
}

totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in enriched {
    return {
        NA: acc.NA + (row.amount if row.region == "NA" else 0),
        EU: acc.EU + (row.amount if row.region == "EU" else 0),
        APAC: acc.APAC + (row.amount if row.region == "APAC" else 0)
    }
}

submitted = submit_result({ answer: totals })
return { totals: totals, submitted: submitted }
